package com.troday.api.entity;
import jakarta.persistence.*;
@Entity @Table(name="contract_templates") public class ContractTemplate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="created_by_id") private Long createdById; private String name; private Integer version=1; @Lob private String content; private Boolean active=true; public Long getId(){return id;} public Long getCreatedById(){return createdById;} public void setCreatedById(Long v){createdById=v;} public String getName(){return name;} public void setName(String v){name=v;} public Integer getVersion(){return version;} public void setVersion(Integer v){version=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public Boolean getActive(){return active;} public void setActive(Boolean v){active=v;} }
